const stories=[{"id":0,"title":"Пока город спит","tags":["Мистика","Романтика"],"image":"photo-1519608487953-e999c86e7455","label":"НОВАЯ ИСТОРИЯ","description":"Ты возвращаешься в город, который обещала забыть. Но кто-то всё это время ждал.","place":"СЕВЕРНЫЙ ГОРОД • 02:17","scenes":[]},{"id":1,"title":"Не случайные","tags":["Романтика","Драма"],"image":"photo-1516483638261-f4dbaf036963","label":"ЛЕТНИЙ ВАЙБ","description":"Месяц у моря, квартира на двоих и договор — ни во что серьёзное не ввязываться.","place":"ИТАЛЬЯНСКОЕ ПОБЕРЕЖЬЕ • 18:40","scenes":[]},{"id":2,"title":"Тёмная сторона Луны","tags":["Приключения","Драма"],"image":"photo-1446776811953-b23d57bd21aa","label":"ДАЛЕКО ОТ ЗЕМЛИ","description":"На орбитальной станции исчезает связь. В невесомости сложнее всего держать дистанцию.","place":"СТАНЦИЯ «ЛУНА-9» • 04:06","scenes":[]}];
let state;try{state=JSON.parse(localStorage.getItem('between-lines-episodes-v2'))||{saved:[],runs:{}}}catch{state={saved:[],runs:{}}}let view='all',filter='Все',query='',active=0;const $=s=>document.querySelector(s);const imageUrl=(s,w=1000)=>['assets/city.png','assets/summer.png','assets/moon.png'][s.id];function save(){try{localStorage.setItem('between-lines-episodes-v2',JSON.stringify(state))}catch{}$('#mycount').textContent=Object.keys(state.runs).length}function render(){const list=stories.filter(s=>(view==='all'||(view==='saved'?state.saved.includes(s.id):state.runs[s.id]))&&(filter==='Все'||s.tags.includes(filter))&&s.title.toLowerCase().includes(query));$('#cards').innerHTML=list.map(s=>`<article class="card"><div class="cover theatre-stage"><img src="${imageUrl(s)}" alt="" loading="lazy"><button class="card-open" data-preview="${s.id}" aria-label="Об истории «${s.title}»"></button>${s.id===1?'':'<span class="cover-label">В разработке</span>'}<button class="bookmark" data-save="${s.id}" aria-label="Избранное: ${s.title}" aria-pressed="${state.saved.includes(s.id)}">${state.saved.includes(s.id)?'♥':'♡'}</button></div><h3><button class="preview-name" data-preview="${s.id}">${s.title}</button></h3><div class="story-summary"><p>${s.description}</p><button class="story-details" data-preview="${s.id}">${s.id===1?"Открыть историю":"Об истории"} <span aria-hidden="true">→</span></button></div></article>`).join('')||'<p class="empty">Здесь пока тихо.<br>Выбери историю в библиотеке или попробуй другой поиск.</p>';$('#section-title').innerHTML=`${view==='mine'?'Мои истории':view==='saved'?'Избранное':'Коллекция историй'}<span>${String(list.length).padStart(2,'0')}</span>`;save()}
function play(id){active=id;if(!state.runs[id])state.runs[id]={step:0,trust:0,truth:0,boundary:0};save();showScene();if(!$('#reader').open)$('#reader').showModal();document.body.style.overflow='hidden';requestAnimationFrame(()=>{$('#reader').scrollTop=state.runs[id].scroll||0})}function showScene(){renderReadingScene()}function closeReader(){$('#reader').close();document.body.style.overflow='';render()}document.addEventListener('click',e=>{const p=e.target.closest('[data-play]');if(p)play(Number(p.dataset.play));const b=e.target.closest('[data-save]');if(b){const id=Number(b.dataset.save);state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render()}const c=e.target.closest('[data-choice]');if(c){if(active===1&&typeof chooseSummer==='function'){chooseSummer(Number(c.dataset.choice));return}const r=state.runs[active],choice=stories[active].scenes[r.step][2][Number(c.dataset.choice)];r[choice[1]]++;r.step++;r.beat=0;r.scroll=0;save();showScene()}if(e.target.closest('[data-replay]'))restart();if(e.target.closest('[data-library]'))closeReader()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===b));render();$('#library').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.chip').forEach(n=>n.classList.toggle('selected',n===b));render()});$('.search input').oninput=e=>{query=e.target.value.toLowerCase().trim();render()};function restart(){state.runs[active]={step:0,trust:0,truth:0,boundary:0};save();showScene()}$('#restart').onclick=restart;$('#exit').onclick=closeReader;$('#reader').addEventListener('close',()=>{document.body.style.overflow='';render()});function info(html){$('#info-content').innerHTML=html;$('#info').showModal()}$('#profile').onclick=()=>info(`<div class="eyebrow">ТВОЯ ЧИТАТЕЛЬСКАЯ КОМНАТА</div><h2>Истории остаются.</h2><p>Начато историй: ${Object.keys(state.runs).length}<br>Прочитано: ${Object.entries(state.runs).filter(([id,r])=>r.step>=stories[id].scenes.length).length}<br>В избранном: ${state.saved.length}</p><p>Твой прогресс хранится в этом браузере. Возвращайся, когда захочется ещё одной истории.</p>`);$('#about').onclick=()=>info('<div class="eyebrow">МЕЖДУ СТРОК</div><h2>Твоя версия важна.</h2><p>Первые серии трёх оригинальных интерактивных историй о близости, честности и личных границах. Все персонажи — взрослые.</p><p>Выборы формируют характер героини и отношения. Здесь нет платных ответов и таймера ожидания.</p>');$('#info .close').onclick=()=>$('#info').close();render();

let scrollSaveTimer;$('#reader').addEventListener('scroll',()=>{clearTimeout(scrollSaveTimer);scrollSaveTimer=setTimeout(()=>{if($('#reader').open&&state.runs[active]){state.runs[active].scroll=$('#reader').scrollTop;save()}},200)});
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
